 /// Reusable first-partials scratch for [`refine_line_surface_point`].
 /// The specialized first-order solve returns the general derivative table's
 /// partials bit for bit, with verified span hints and one fused contraction.
+#[derive(Clone, Copy, Default)]
+struct SimEntry {
+    key: Option<(u64, u64)>,
+    partials: bool,
+}
+struct SimCache<const N: usize> { entries: [SimEntry; N] }
+impl<const N: usize> Default for SimCache<N> {
+    fn default() -> Self { Self { entries: [SimEntry::default(); N] } }
+}
+impl<const N: usize> SimCache<N> {
+    fn index(key: (u64, u64)) -> usize {
+        let hash = key.0.wrapping_mul(0x9e37_79b9_7f4a_7c15).rotate_left(17)
+            ^ key.1.wrapping_mul(0xbf58_476d_1ce4_e5b9);
+        ((hash >> 58) as usize) & (N - 1)
+    }
+    fn point(&mut self, key: (u64, u64)) -> bool {
+        let entry = &mut self.entries[Self::index(key)];
+        if entry.key == Some(key) { true } else {
+            *entry = SimEntry { key: Some(key), partials: false }; false
+        }
+    }
+    fn partials(&mut self, key: (u64, u64)) -> bool {
+        let entry = &mut self.entries[Self::index(key)];
+        let hit = entry.key == Some(key) && entry.partials;
+        *entry = SimEntry { key: Some(key), partials: true };
+        hit
+    }
+}
