+//! Observation-only diagnostic overlay; never shipped or timed.
+#![allow(missing_docs)]
+use std::collections::BTreeMap;
+use std::cell::RefCell;
+use remus_math::vec::{Point3, Vec3};
+use remus_topology::face::FaceId;
+use remus_math::surfaces::ToroidalSurface;
+use remus_math::nurbs::surface::NurbsSurface;
+#[derive(Default, Debug)]
+pub struct KindCounts {
+ pub calls: u64, pub positive_roots: u64, pub zero_positive_calls: u64,
+ pub accepted_crossings: u64, pub trim_rejected_roots: u64, pub errors: u64,
+ pub exact_repeated_carrier_ray_calls: u64,
+ pub per_face: BTreeMap<usize, [u64; 3]>,
+ keys: BTreeMap<Vec<u64>, u64>,
+}
+#[derive(Default, Debug)]
+pub struct Counts { pub enabled: bool, pub torus: KindCounts, pub nurbs: KindCounts }
+std::thread_local! { static COUNTS: RefCell<Counts> = RefCell::new(Counts::default()); }
+pub fn configure(enabled: bool) {
+ COUNTS.with(|c| { if enabled { *c.borrow_mut()=Counts { enabled:true,..Counts::default() }; }
+                  else { c.borrow_mut().enabled=false; } });
+}
+pub fn drain() -> Counts { COUNTS.with(|c| std::mem::take(&mut *c.borrow_mut())) }
+fn enabled() -> bool { COUNTS.with(|c| c.borrow().enabled) }
+fn ray(key: &mut Vec<u64>, origin: Point3, direction: Vec3) {
+ key.extend(origin.0.into_iter().chain(direction.0).map(f64::to_bits));
+}
+fn record(nurbs: bool, face: FaceId, key: Vec<u64>, roots: usize, result: Option<u32>) {
+ COUNTS.with(|c| {
+  let mut all=c.borrow_mut();
+  let c=if nurbs { &mut all.nurbs } else { &mut all.torus };
+  c.calls+=1;c.positive_roots+=roots as u64;c.zero_positive_calls+=u64::from(roots==0);
+  let previous=c.keys.entry(key).or_default();
+  c.exact_repeated_carrier_ray_calls+=u64::from(*previous>0);*previous+=1;
+  let row=c.per_face.entry(face.index()).or_default();row[0]+=1;row[1]+=roots as u64;
+  if let Some(accepted)=result { c.accepted_crossings+=u64::from(accepted);
+    c.trim_rejected_roots+=(roots as u64).saturating_sub(u64::from(accepted));row[2]+=u64::from(accepted); }
+  else { c.errors+=1; }
+ });
+}
+pub fn torus(face: FaceId, t: &ToroidalSurface, origin: Point3, direction: Vec3, roots: usize, result: Option<u32>) {
+ if !enabled() { return; }
+ let mut key: Vec<_>=t.center().0.into_iter().chain(t.x_axis().0).chain(t.y_axis().0).chain(t.z_axis().0)
+   .chain([t.major_radius(),t.minor_radius()]).map(f64::to_bits).collect();
+ ray(&mut key,origin,direction);record(false,face,key,roots,result);
+}
+pub fn nurbs(face: FaceId, s: &NurbsSurface, origin: Point3, direction: Vec3, roots: usize, result: Option<u32>) {
+ if !enabled() { return; }
